UPDATE loan_account
SET loan_principal_balance = loan_principal_balance - #{amount}
WHERE loan_account_id = #{loanAccountId}

UPDATE loan_account
SET loan_status_id = #{loanStatus}
WHERE loan_account_id = #{loanAccountId}

mapper.select:


SELECT la.loan_account_id
FROM loan_account la
WHERE la.loan_account_id > #{afterLoanAccountId}
  AND COALESCE((SELECT lsj.loan_judgment_status_id
                FROM loan_status_judgment lsj
                WHERE lsj.loan_account_id = la.loan_account_id
                ORDER BY lsj.loan_status_judgment_id DESC
                LIMIT 1), #{normal}) <> #{paidOff}
ORDER BY la.loan_account_id
LIMIT #{limit}
